11	/*!
12	 * \file flash_attention_score_enhance_drop_mask_adapter.h
13	 * \brief
14	 */
15	
16	#ifndef FLASH_ATTENTION_SCORE_ENHANCE_DROP_MASK_ADAPTER_H
17	#define FLASH_ATTENTION_SCORE_ENHANCE_DROP_MASK_ADAPTER_H
18	
19	#include "kernel_operator.h"
20	#include "kernel_tiling/kernel_tiling.h"
21	
22	class FlashAttentionScoreEnhanceDropMaskAdapter {
23	  public:
24	    __aicore__ inline FlashAttentionScoreEnhanceDropMaskAdapter() {}
25	    __aicore__ inline void Init(__gm__ uint8_t *dropMask,
26	                                __gm__ uint8_t *workspace,
27	                                const FlashAttentionScoreEnhanceGeneralTilingData *__restrict tiling,
28	                                AscendC::TPipe *tPipe);
29	    __aicore__ inline void Process();
30	    __aicore__ inline void CopyIn(int64_t offset, int32_t calSize);
31	    __aicore__ inline void Compute(int32_t calSize,
32	                                   AscendC::LocalTensor<half> &dropMaskSelSrc,
33	                                   const AscendC::BinaryRepeatParams &binaryRepeatParams);
34	    __aicore__ inline void CopyOut(int64_t offset, int32_t calSize);
35	    __aicore__ inline void SyncAllCores();
36	
37	    template <typename T1, typename T2> __aicore__ inline T1 CeilDiv(T1 a, T2 b)
38	    {
39	        if (b == 0) {
40	            return 0;
41	        }
42	        return (a + b - 1) / b;
43	    };
44	
45	    template <typename T1, typename T2> __aicore__ inline T1 Min(T1 a, T2 b)
46	    {
47	        return (a > b) ? (b) : (a);
48	    };
49	
50	    int32_t blockIdx;
51	    AscendC::TPipe *pipe;
52	    const FlashAttentionScoreEnhanceGeneralTilingData *__restrict tilingData;
53	
54	    AscendC::GlobalTensor<uint8_t> dropMaskGm;
55	    AscendC::GlobalTensor<uint8_t> outputGm;
56	    AscendC::TQue<AscendC::QuePosition::VECIN, 1> dropMaskInputQueue;
57	    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> dropMaskOutputQueue;
58	    AscendC::TBuf<> dropMaskSelSrcTBuf;
59	    AscendC::TBuf<> dropMaskSelResTBuf;
60	
61	    constexpr static int32_t SELECT_MAX_MASK = 128;
62	    constexpr static int32_t SELECT_MAX_SRC_STRIDE = 16;
63	    constexpr static int32_t SELECT_MAX_REPEAT = 255;
64	    constexpr static int32_t SELECT_MAX_REPEAT_MASK = SELECT_MAX_MASK * SELECT_MAX_REPEAT;
65	};
66	
67	__aicore__ inline void
68	FlashAttentionScoreEnhanceDropMaskAdapter::Init(__gm__ uint8_t *dropMask,
69	                                                __gm__ uint8_t *workspace,
70	                                                const FlashAttentionScoreEnhanceGeneralTilingData *__restrict tiling,
71	                                                AscendC::TPipe *tPipe)
72	{
73	    pipe = tPipe;
74	    tilingData = tiling;
75	    blockIdx = AscendC::GetBlockIdx();
76	
77	    dropMaskGm.SetGlobalBuffer(dropMask);
78	    outputGm.SetGlobalBuffer(workspace, CeilDiv(tiling->dropmaskParams.shapeTotalSize, 512) * 512);
79	    pipe->InitBuffer(dropMaskInputQueue, 1, tiling->dropmaskParams.baseUbCalSize / AscendC::ONE_BYTE_BIT_SIZE);
80	    pipe->InitBuffer(dropMaskOutputQueue, 1, tiling->dropmaskParams.baseUbCalSize);
81	    pipe->InitBuffer(dropMaskSelSrcTBuf, tiling->dropmaskParams.baseUbCalSize * sizeof(half));
82	    pipe->InitBuffer(dropMaskSelResTBuf, tiling->dropmaskParams.baseUbCalSize * sizeof(half));
83	}
84	
85	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::Process()
86	{
87	    // 输入非对齐时，bit[gm] -> select(fp16)[ub] -> bool[ub] -> bool[gm]
88	    // 单次ub计算量为x个元素，空间占用：x/8 * 1 [1个 uint8]+ 2x * 2[2个fp16,select的src和res] + x * 1 [1个uint8]
89	    int64_t multiCoreFactorSize = tilingData->dropmaskParams.multiCoreFactorSize; // BN2GS1S2 / 单次UB计算量 / coreNum
90	    int64_t multiCoreTotalSize = tilingData->dropmaskParams.multiCoreTotalSize; // 绑多核轴总量，BN2GS1S2 / 单次UB计算量
91	    int64_t coreOffset = multiCoreFactorSize * blockIdx;
92	    int64_t shapeTotalSize = tilingData->dropmaskParams.shapeTotalSize; // BN2GS1S2
93	    int64_t singleCoreCalNum = Min(multiCoreFactorSize, multiCoreTotalSize - coreOffset);
94	    if (singleCoreCalNum <= 0) {
95	        SyncAllCores();
96	        return;
97	    }
98	
99	    int32_t baseUbCalSize = tilingData->dropmaskParams.baseUbCalSize;
100	    AscendC::LocalTensor<half> dropMaskSelSrc = dropMaskSelSrcTBuf.template Get<half>();
101	    AscendC::Duplicate<half>(dropMaskSelSrc, 1.0, baseUbCalSize);
102	
103	    AscendC::BinaryRepeatParams binaryRepeatParams;
104	    binaryRepeatParams.src0BlkStride = 1;
105	    binaryRepeatParams.src0RepStride = 0;
106	    binaryRepeatParams.src1BlkStride = 1;
107	    binaryRepeatParams.src1RepStride = 0;
108	    binaryRepeatParams.dstBlkStride = 1;
109	    binaryRepeatParams.dstRepStride = 8; // 8: 256B / 32B
110	    AscendC::PipeBarrier<PIPE_V>();
111	    for (int64_t loop = 0; loop < singleCoreCalNum; ++loop) {
112	        int64_t totalOffset = coreOffset + loop;
113	        int32_t realBaseUbCalSize = baseUbCalSize;
114	        if (unlikely((totalOffset + 1) * baseUbCalSize > shapeTotalSize)) {
115	            realBaseUbCalSize = static_cast<int32_t>(shapeTotalSize - totalOffset * baseUbCalSize);
116	        }
117	
118	        CopyIn(totalOffset * baseUbCalSize, realBaseUbCalSize);
119	        Compute(realBaseUbCalSize, dropMaskSelSrc, binaryRepeatParams);
120	        CopyOut(totalOffset * baseUbCalSize, realBaseUbCalSize);
121	    }
122	
123	    SyncAllCores();
124	}
125	
126	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::CopyIn(int64_t offset, int32_t calSize)
127	{
128	    AscendC::LocalTensor<uint8_t> dropMaskUb = dropMaskInputQueue.template AllocTensor<uint8_t>();
129	    AscendC::DataCopyParams dataCopyParams;
130	    dataCopyParams.blockCount = 1;
131	    dataCopyParams.dstStride = 0;
132	    dataCopyParams.blockLen = CeilDiv(calSize, AscendC::ONE_BYTE_BIT_SIZE);
133	    dataCopyParams.srcStride = 0;
134	    AscendC::DataCopyPadParams dataCopyPadParams;
135	    DataCopyPad(dropMaskUb, dropMaskGm[offset >> 3], dataCopyParams, dataCopyPadParams); // 右移3位表示除8
136	
137	    dropMaskInputQueue.EnQue(dropMaskUb);
138	}
139	
140	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::Compute(
141	    int32_t calSize, AscendC::LocalTensor<half> &dropMaskSelSrc, const AscendC::BinaryRepeatParams &binaryRepeatParams)
142	{
143	    AscendC::LocalTensor<half> dropMaskSelRes = dropMaskSelResTBuf.template Get<half>();
144	    AscendC::LocalTensor<uint8_t> dropMaskUb = dropMaskInputQueue.template DeQue<uint8_t>();
145	    AscendC::PipeBarrier<PIPE_V>();
146	
147	    int32_t loop = calSize / SELECT_MAX_REPEAT_MASK;
148	    for (int32_t idx = 0; idx < loop; ++idx) {
149	        Select(dropMaskSelRes[SELECT_MAX_MASK * idx],
150	               dropMaskUb[SELECT_MAX_SRC_STRIDE * idx],
151	               dropMaskSelSrc,
152	               static_cast<half>(0),
153	               AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE,
154	               SELECT_MAX_MASK,
155	               SELECT_MAX_REPEAT,
156	               binaryRepeatParams);
157	    }
158	
159	    int32_t repeat = CeilDiv(calSize, SELECT_MAX_MASK) - SELECT_MAX_REPEAT * loop;
160	    Select(dropMaskSelRes[SELECT_MAX_MASK * loop],
161	           dropMaskUb[SELECT_MAX_SRC_STRIDE * loop],
162	           dropMaskSelSrc,
163	           static_cast<half>(0),
164	           AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE,
165	           Min(calSize, SELECT_MAX_MASK),
166	           repeat,
167	           binaryRepeatParams);
168	
169	    AscendC::PipeBarrier<PIPE_V>();
170	    dropMaskInputQueue.FreeTensor(dropMaskUb);
171	
172	    AscendC::LocalTensor<uint8_t> dropMaskOutUb = dropMaskOutputQueue.template AllocTensor<uint8_t>();
173	    Cast(dropMaskOutUb, dropMaskSelRes, AscendC::RoundMode::CAST_NONE, calSize);
174	    dropMaskOutputQueue.EnQue(dropMaskOutUb);
175	}
176	
177	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::CopyOut(int64_t offset, int32_t calSize)
178	{
179	    AscendC::LocalTensor<uint8_t> dropMaskOutUb = dropMaskOutputQueue.template DeQue<uint8_t>();
180	    AscendC::PipeBarrier<PIPE_V>();
181	    AscendC::DataCopyParams dataCopyParams;
182	    dataCopyParams.blockCount = 1;
183	    dataCopyParams.blockLen = calSize;
184	    dataCopyParams.dstStride = 0;
185	    dataCopyParams.srcStride = 0;
186	    DataCopyPad(outputGm[offset], dropMaskOutUb, dataCopyParams);
187	    dropMaskOutputQueue.FreeTensor(dropMaskOutUb);
188	}
189	
190	__aicore__ inline void FlashAttentionScoreEnhanceDropMaskAdapter::SyncAllCores()
191	{
192	    AscendC::SyncAll();
193	}
194	
195	#endif // FLASH_ATTENTION_SCORE_ENHANCE_DROP_MASK_ADAPTER_H
196

