11	/*!
12	 * \file flash_attention_score_enhance_empty_tensor.h
13	 * \brief
14	 */
15	
16	#ifndef FLASH_ATTENTION_SCORE_ENHANCE_EMPTY_TENSOR_H
17	#define FLASH_ATTENTION_SCORE_ENHANCE_EMPTY_TENSOR_H
18	
19	#include "kernel_operator.h"
20	#include "kernel_tiling/kernel_tiling.h"
21	#include "flash_attention_score_enhance_tiling.h"
22	
23	using namespace fase_tiling;
24	
25	template <typename INPUT_T> class FlashAttentionScoreEnhanceEmptyTensor {
26	public:
27	    __aicore__ inline FlashAttentionScoreEnhanceEmptyTensor(){};
28	    __aicore__ inline void Init(__gm__ uint8_t *softmaxMax, __gm__ uint8_t *softmaxSum, __gm__ uint8_t *attentionOut,
29	                                const FlashAttentionScoreEnhanceTilingData *__restrict tiling);
30	    __aicore__ inline void Process();
31	
32	protected:
33	    AscendC::GlobalTensor<float> softmaxMaxGm;
34	    AscendC::GlobalTensor<float> softmaxSumGm;
35	    AscendC::GlobalTensor<INPUT_T> attentionOutGm;
36	    uint32_t tmpBlockIdx;
37	    const FlashAttentionScoreEnhanceTilingData *__restrict tilingData;
38	    __aicore__ inline void ComputeEachCore();
39	};
40	
41	template <typename INPUT_T>
42	__aicore__ inline void
43	FlashAttentionScoreEnhanceEmptyTensor<INPUT_T>::Init(__gm__ uint8_t *softmaxMax, __gm__ uint8_t *softmaxSum,
44	                                              __gm__ uint8_t *attentionOut,
45	                                              const FlashAttentionScoreEnhanceTilingData *__restrict tiling)
46	{
47	    tmpBlockIdx = AscendC::GetBlockIdx();
48	    tilingData = tiling;
49	    softmaxMaxGm.SetGlobalBuffer((__gm__ float *)softmaxMax);
50	    softmaxSumGm.SetGlobalBuffer((__gm__ float *)softmaxSum);
51	    attentionOutGm.SetGlobalBuffer((__gm__ INPUT_T *)attentionOut);
52	}
53	
54	template <typename INPUT_T> __aicore__ inline void FlashAttentionScoreEnhanceEmptyTensor<INPUT_T>::ComputeEachCore()
55	{
56	    uint32_t coreNum = tilingData->emptyInputTilingData.coreNum;
57	    uint32_t attentionOutFormerNum = tilingData->emptyInputTilingData.attentionOutFormerNum;
58	    uint32_t attentionOutTailNum = tilingData->emptyInputTilingData.attentionOutTailNum;
59	    uint32_t softmaxMaxFormerNum = tilingData->emptyInputTilingData.softmaxMaxFormerNum;
60	    uint32_t softmaxMaxTailNum = tilingData->emptyInputTilingData.softmaxMaxTailNum;
61	    uint64_t attentionOutSingleCoreDataSize = tilingData->emptyInputTilingData.attentionOutSingleCoreDataSize;
62	    uint64_t attentionOutTailCoreDataSize = tilingData->emptyInputTilingData.attentionOutTailCoreDataSize;
63	    uint64_t softmaxMaxSingleCoreDataSize = tilingData->emptyInputTilingData.softmaxMaxSingleCoreDataSize;
64	    uint64_t softmaxMaxTailCoreDataSize = tilingData->emptyInputTilingData.softmaxMaxTailCoreDataSize;
65	    uint64_t attentionOutLastCoreDataSize = tilingData->emptyInputTilingData.attentionOutLastCoreDataSize;
66	    uint64_t attentionOutLastCoreIndex = tilingData->emptyInputTilingData.attentionOutLastCoreIndex;
67	
68	    // 初始化 attentionOut
69	    if (attentionOutFormerNum == coreNum || (attentionOutFormerNum + attentionOutTailNum) < coreNum) {
70	        if (tmpBlockIdx < attentionOutFormerNum - 1) {
71	            AscendC::InitOutput<INPUT_T>(attentionOutGm[tmpBlockIdx * attentionOutSingleCoreDataSize],
72	                                         attentionOutSingleCoreDataSize, static_cast<INPUT_T>(0.0));
73	        } else if (tmpBlockIdx == attentionOutFormerNum - 1) {
74	            AscendC::InitOutput<INPUT_T>(attentionOutGm[attentionOutLastCoreIndex], attentionOutLastCoreDataSize,
75	                                         static_cast<INPUT_T>(0.0));
76	        }
77	    } else {
78	        if (tmpBlockIdx < attentionOutFormerNum) {
79	            AscendC::InitOutput<INPUT_T>(attentionOutGm[tmpBlockIdx * attentionOutSingleCoreDataSize],
80	                                         attentionOutSingleCoreDataSize, static_cast<INPUT_T>(0.0));
81	        } else if (tmpBlockIdx >= attentionOutFormerNum && tmpBlockIdx < coreNum - 1) {
82	            AscendC::InitOutput<INPUT_T>(
83	                attentionOutGm[attentionOutFormerNum * attentionOutSingleCoreDataSize +
84	                               (tmpBlockIdx - attentionOutFormerNum) * attentionOutTailCoreDataSize],
85	                attentionOutTailCoreDataSize, static_cast<INPUT_T>(0.0));
86	        } else if (tmpBlockIdx == coreNum - 1) {
