1020	            int64_t loopS1EndIdx;
1021	            bool lastBn = bngIdx == (bngEndIdx - 1);
1022	            if (lessThanS1Outer || lastBn) {
1023	                realS1EndIdx = residual;
1024	            }
1025	            bool needFakePair = (realS1EndIdx - s1StartIdx) % 2 ? true : false;
