          bool enableL1Reuse,
          bool hasRope>
__aicore__ inline void FlashAttentionScoreEnhanceS1s2Bn2gs1<implMode,
                                                            layOutType,
                                                            hasPse,
                                                            hasAtten,
                                                            hasDrop,
                                                            INPUT_T,
                                                            T,
                                                            isBasicBlock,
                                                            bmm1Format,
                                                            enableL1Reuse,
                                                            hasRope>::GetBNIdx(const int64_t &multiCoreInnerOffset,
                                                                               const int64_t &multiCoreInnerLimit)
{
    bngStartIdx = multiCoreInnerOffset / this->tilingData->coreParams.s1OuterSize;
    bngEndIdx = CeilDiv(multiCoreInnerLimit, this->tilingData->coreParams.s1OuterSize);
}

template <ImplModeEnum implMode,
          LayOutTypeEnum layOutType,
          bool hasPse,
          bool hasAtten,
          bool hasDrop,
          typename INPUT_T,
          typename T,
          bool isBasicBlock,
          CubeFormat bmm1Format,
          bool enableL1Reuse,
